});

// 2. Mengambil data JSON dari respons server
const responseData = pm.response.json();

// 3. Memeriksa apakah format data berupa array atau objek pembungkus pagination
// (Disesuaikan dengan struktur controller kamu yang mengembalikan objek { data, page, limit, total })
pm.test("Response memiliki struktur data yang benar", function () {
    // Jika controller menggunakan pagination, data ada di dalam responseData.data
    // Jika controller langsung mengembalikan array, gunakan responseData
    const listData = responseData.data || responseData;
    pm.expect(listData).to.be.an('array');
});

// 4. Memastikan formasi yang sebelumnya dibuat (formasiId) ada di dalam daftar
pm.test("Daftar formasi berisi formasi yang baru dibuat", function () {
    const listData = responseData.data || responseData;
    const formasiId = pm.environment.get("formasiId");
    
    if (formasiId) {
        const ids = listData.map(item => item._id);
        pm.expect(ids).to.include(formasiId);
    } else {
        console.log("Variabel environment 'formasiId' belum ada, lewati pengecekan ID spesifik.");
    }
});

